package com.yeyamo_mobile.api.culture_service.infrastructure.persistence;import com.yeyamo_mobile.api.culture_service.domain.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.JpaRepository;public final class ChallengeRepositories{private ChallengeRepositories(){}public interface Challenges extends JpaRepository<CultureChallenge,UUID>{Page<CultureChallenge>findByStatus(CultureChallenge.Status status,Pageable p);}public interface Prompts extends JpaRepository<CultureChallengePrompt,UUID>{List<CultureChallengePrompt>findByChallengeIdOrderByDisplayOrder(UUID id);}public interface Participants extends JpaRepository<CultureChallengeParticipant,UUID>{Optional<CultureChallengeParticipant>findByChallengeIdAndUserId(UUID challenge,String user);List<CultureChallengeParticipant>findByUserIdOrderByJoinedAtDesc(String user);}public interface Submissions extends JpaRepository<CultureChallengeSubmission,UUID>{Optional<CultureChallengeSubmission>findByChallengeIdAndUserId(UUID challenge,String user);Page<CultureChallengeSubmission>findByChallengeIdAndStatus(UUID challenge,CultureChallengeSubmission.Status status,Pageable p);}public interface Consents extends JpaRepository<CultureConsentDeclaration,UUID>{}}
